} from '@iwsdk/core';

import {
	createPlayerShip,
	createEnemyShip,
	createCannonball,
	createTreasure,
	createExplosion,
	createOceanPlane,
	createSeaMine,
	createWaterSplash,
	createStarfield,
	getScheme,
	COLOR_SCHEMES,
